-- Run after the isolated fixture and migration. Does not send WhatsApp or call providers.
\set ON_ERROR_STOP on
begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; end $$;
create function pg_temp.reject(statement text,label text) returns void language plpgsql as $$ begin
  begin execute statement; exception when others then return; end;
  raise exception 'FAIL accepted: %',label;
end $$;
insert into tenants values('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002');
insert into profiles values('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','admin','active'),('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000002','admin','active');
insert into customers values('20000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','Pessoa de teste','test@example.invalid','5500000000000',false);
insert into whatsapp_instances values('30000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001',true);
insert into whatsapp_chats values('40000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','full','Pessoa de teste');
insert into whatsapp_messages values('50000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','inbound','document');
insert into tenant_ai_config values('00000000-0000-0000-0000-000000000001','native');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true),set_config('request.jwt.claim.role','authenticated',true);
select public.ai_sales_workflow_save('{"enabled":true,"sdr_name":"Davi","closer_name":"Clara"}',0);
select pg_temp.reject($q$select public.ai_sales_workflow_save('{"sdr_name":"Davi","closer_name":"Clara"}',0)$q$,'stale configuration');
select pg_temp.reject($q$select * from public.ai_sales_workflow_sessions$q$,'no direct health access for admin');
select pg_temp.reject($q$select public.ai_sales_workflow_action('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','record_intake','{}',0,'bad')$q$,'authenticated cannot act as worker');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select pg_temp.assert((select count(*)=0 from public.ai_sales_workflow_config),'RLS other tenant config');
select pg_temp.assert(public.ai_sales_workflow_overview()='[]'::jsonb,'other tenant overview');
reset role;
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select pg_temp.reject($q$select public.ai_sales_workflow_action('00000000-0000-0000-0000-000000000002','40000000-0000-0000-0000-000000000001','record_intake','{"consent":"yes"}',0,'cross')$q$,'cross tenant chat');
select pg_temp.reject($q$select public.ai_sales_workflow_action('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','record_intake','{"health_reported":"yes"}',0,'no-consent')$q$,'health before consent');
select public.ai_sales_workflow_action('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','record_intake','{"consent":"yes","existing_client":"no","benefit":"retirement","pays_ir":"no","health_reported":"no","has_documents":"no"}',0,'intake');

select pg_temp.assert((select status='needed' from ai_previdas_cases),'missing report creates optional pending evaluation');
select pg_temp.reject($q$select ai_sales_workflow_action('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','record_previdas','{"status":"scheduled","revision":0}',1,'fake-confirm')$q$,'agent cannot confirm appointment');
select pg_temp.reject($q$select ai_sales_workflow_action('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','record_previdas','{"status":"requested","revision":0}',1,'no-authorization')$q$,'specific referral authorization required');
select ai_sales_workflow_action('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','record_previdas','{"status":"requested","revision":0,"authorized":true,"availability":"Manhã","next_action_at":"2026-12-01T12:00:00Z"}',1,'request');
select ai_sales_workflow_action('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','record_previdas','{"status":"requested","revision":0,"authorized":true,"next_action_at":"2026-12-01T12:00:00Z"}',1,'request');
select pg_temp.assert((select count(*)=1 from ai_previdas_events),'worker retry creates single event');
select pg_temp.assert((select status='requested' and appointment_at is null from ai_previdas_cases),'request never confirms appointment');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true),set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select pg_temp.assert(ai_previdas_overview()='[]'::jsonb,'other tenant sees no referral');
select pg_temp.reject($q$select ai_previdas_update('40000000-0000-0000-0000-000000000001','{"status":"reschedule"}',1)$q$,'other tenant cannot update');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select pg_temp.reject($q$select * from ai_previdas_cases$q$,'no direct table access');
select pg_temp.reject($q$select ai_previdas_update('40000000-0000-0000-0000-000000000001','{"status":"scheduled"}',1)$q$,'confirmation requires date modality and reference');
select ai_previdas_update('40000000-0000-0000-0000-000000000001','{"status":"scheduled","appointment_at":"2026-12-02T12:00:00Z","modality":"online","confirmation_ref":"synthetic-confirmation","next_action_at":"2026-12-02T10:00:00Z"}',1);
select pg_temp.reject($q$select ai_previdas_update('40000000-0000-0000-0000-000000000001','{"status":"reschedule","next_action_at":"2026-12-03T12:00:00Z"}',1)$q$,'stale update rejected');
select ai_previdas_update('40000000-0000-0000-0000-000000000001','{"status":"reschedule","next_action_at":"2026-12-03T12:00:00Z"}',2);
select pg_temp.assert((ai_previdas_overview()->0->>'appointment_at') is null,'reschedule clears old date');
select ai_previdas_update('40000000-0000-0000-0000-000000000001','{"status":"scheduled","appointment_at":"2026-12-04T12:00:00Z","modality":"online","confirmation_ref":"synthetic-rebooking","next_action_at":"2026-12-04T10:00:00Z"}',3);
select ai_previdas_update('40000000-0000-0000-0000-000000000001','{"status":"awaiting_report","confirmation_ref":"synthetic-attendance","next_action_at":"2026-12-05T10:00:00Z"}',4);
select pg_temp.reject($q$select ai_previdas_update('40000000-0000-0000-0000-000000000001','{"status":"report_received","report_document_id":"90000000-0000-0000-0000-000000000001"}',5)$q$,'invented report rejected');
reset role;
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select ai_sales_workflow_action('00000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','register_document','{"message_id":"50000000-0000-0000-0000-000000000001","category":"medical"}',2,'medical');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select ai_previdas_update('40000000-0000-0000-0000-000000000001',jsonb_build_object('status','report_received','report_document_id',ai_previdas_overview()->0->'documents'->0->>'id'),5);
select pg_temp.assert(ai_previdas_overview()->0->>'status'='report_received','received report returns to document review');
reset role;
select pg_temp.assert((select status='received_unreviewed' from ai_sales_workflow_documents),'received is not approved');
select 'All Pre Vidas assertions passed';
rollback;
